def expected_cycle_latency(draft_steps, accept_rate, *, proposal_ns, verifier_ns,
                           catchup_ns, state_management_ns=0):
    outcomes = cycle_outcomes(draft_steps, accept_rate)
    expected = sum(item["probability"]*item["output_tokens"] for item in outcomes)
    catchup = sum(item["probability"]*float(catchup_ns[item["accepted_draft_tokens"]]) for item in outcomes)
    values = [float(proposal_ns), float(verifier_ns), catchup, float(state_management_ns)]
    if any(not math.isfinite(x) or x < 0 for x in values):
        raise ValueError("cycle costs must be finite and nonnegative")
    total = sum(values)
    return {"proposal_time_ns": values[0], "verifier_time_ns": values[1],
            "catchup_time_ns": catchup, "state_management_time_ns": values[3],
            "expected_tokens": expected, "total_time_ns": total, "tpot_ns": total/expected}


