def _candidate(config, timings, probabilities, cap, output, batch):
    counts = _cycle_counts(output - 1, cap, probabilities)
    speculative_cycles = sum(counts[1:])
    initialization = float(speculative_cycles > 0)
    stage = {
        'prefill': dict(timings['prefill']),
        'verify': {r: sum(c * v for c, v in zip(counts, curve)) for r, curve in timings['verify'].items()},
        'draft': {r: v * speculative_cycles for r, v in timings['draft'].items()} if initialization else {},
        'draft_init': {r: v for r, v in timings['draft_init'].items()} if initialization else {},
    }
    pool_demands = dict.fromkeys(config['pools'], 0.0)
    for role_costs in stage.values():
        for role, seconds in role_costs.items():
            pool_demands[config['role_to_pool'][role]] += seconds
    link_demands = {link: value['prefill_seconds'] + sum(c * v for c, v in zip(counts, value['verify_seconds']))
                   + speculative_cycles * value['draft_seconds'] + initialization * value['draft_init_seconds']
                   + int(output > 1) * value['decode_init_seconds']
                   for link, value in timings['links'].items()}
    demands = {**{f'pool:{p}': v for p, v in pool_demands.items()},
               **{f'link:{link}': v for link, v in link_demands.items()}}

def af_transfer_work(*, batch, input_len, query_len, hidden, layers, window, streams):
    """Conservative full mHC residual-stream transfer in both directions per layer."""
    values = (batch, input_len, query_len, hidden, layers, window, streams)
    if any(not isinstance(v, int) or isinstance(v, bool) or v < 1 for v in values):
        raise ValueError('AF dimensions must be positive integers')
    tokens = (layers//2)*input_len + (layers-layers//2)*min(input_len, window)
    width = hidden*streams*2*2  # BF16 residual streams, two boundaries.
    return dict(prefill_bytes=batch*tokens*width,
                verify_bytes=batch*layers*query_len*width, messages=2*layers)


