def allocate_tiers(components, *, sram_capacity, external_capacity, bandwidth_GBps):
    """Place cache, activation reserve, then weights into SRAM; spill the rest."""
    names = ('persistent', 'activation_reserve', 'weights')
    if set(components) - set(names):
        raise ValueError('Unknown memory component')
    values = [sram_capacity, external_capacity, bandwidth_GBps, *components.values()]
    if any(isinstance(v, bool) or not math.isfinite(v) or v < 0 for v in values):
        raise ValueError('Memory capacity, residency and bandwidth must be finite and nonnegative')
    left = sram_capacity
    resident, spilled = {}, {}
    for name in names:
        size = components.get(name, 0)
        resident[name] = min(size, left)
        spilled[name] = size - resident[name]
        left -= resident[name]
    return dict(sram_capacity_bytes=sram_capacity, external_capacity_bytes=external_capacity,
                capacity_bytes=sram_capacity+external_capacity,
                sram_resident_bytes=sum(resident.values()), external_resident_bytes=sum(spilled.values()),
